var raw = items[0].json.text || items[0].json.output || '';
raw = raw.trim();

// Strip markdown fences if present
if (raw.indexOf('```') !== -1) {
  raw = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
}

// Extract only the JSON object — everything from first { to last }
var start = raw.indexOf('{');
var end   = raw.lastIndexOf('}');
if (start === -1 || end === -1) {
  throw new Error('No JSON object found in response. Raw start: ' + raw.substring(0, 200));
}
raw = raw.substring(start, end + 1);

var plan;
try { plan = JSON.parse(raw); }
catch(e) {
  throw new Error('JSON parse failed: ' + e.message + ' | Raw start: ' + raw.substring(0, 300));
}

return [{ json: plan }];

var p = items[0].json;
var c = p.client || {};
var v = p.projectVision || {};
var lss = p.leanSixSigma || {};
var bgt = p.budget || {};
var tl  = p.timeline || {};
var today = new Date().toISOString().split('T')[0];
var safeCompany = (c.company || 'Client').replace(/[^a-zA-Z0-9 ]/g,'').trim().replace(/ +/g,'-');
var fn = 'Project-Plan-' + safeCompany + '-' + today + '.pdf';

// ── Helpers ──────────────────────────────────────────────
function esc(s){ return (s||'').toString().replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function safe(s){ return (s||'').toString(); }
function money(n){ return '$' + (n||0).toLocaleString('en-US'); }
function arr(a){ return Array.isArray(a) ? a : []; }

function badge(priority){
  var colors = {Critical:'#dc2626',High:'#FA4616',Medium:'#f59e0b',Low:'#16a34a'};
  var col = colors[priority] || '#6b7280';
  return '<span style="background:' + col + ';color:#fff;padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700">' + esc(priority) + '</span>';
}

function impactBadge(v){
  var c2 = {High:'#dc2626',Medium:'#f59e0b',Low:'#16a34a'};
  return '<span style="background:' + (c2[v]||'#6b7280') + ';color:#fff;padding:2px 7px;border-radius:8px;font-size:10px;font-weight:700">' + esc(v) + '</span>';
}

function sectionHead(title, subtitle){
  return '<div style="margin:0 0 18px"><h2 style="color:#002657;font-size:17px;border-bottom:2px solid #FA4616;padding-bottom:6px;margin:0 0 4px">' + title + '</h2>' +
    (subtitle ? '<p style="color:#6b7280;font-size:12px;margin:0">' + esc(subtitle) + '</p>' : '') + '</div>';
}

function pb(num){ return '<div style="background:#e5e7eb;border-radius:4px;height:6px;margin-top:4px"><div style="background:#FA4616;height:6px;border-radius:4px;width:' + Math.min(100,num) + '%"></div></div>'; }

function listItems(arr2){
  var out = '<ul style="margin:6px 0;padding-left:18px">';
  arr(arr2).forEach(function(x){ out += '<li style="margin-bottom:3px;font-size:12px">' + esc(x) + '</li>'; });
  return out + '</ul>';
}

function twoCol(label, val){
  return '<tr><td style="padding:5px 10px;font-weight:700;color:#002657;border-bottom:1px solid #e5e7eb;font-size:12px;white-space:nowrap">' + esc(label) + '</td>' +
    '<td style="padding:5px 10px;border-bottom:1px solid #e5e7eb;font-size:12px">' + esc(val) + '</td></tr>';
}

// ── CSS ──────────────────────────────────────────────────
var css = '<style>' +
'@page{margin:12mm 10mm 14mm}' +
'*{box-sizing:border-box}' +
'body{font-family:Arial,Helvetica,sans-serif;margin:0;padding:0;color:#222;font-size:12px;line-height:1.55}' +
'.hdr{background:#002657;padding:14px 18px;display:flex;align-items:center;justify-content:space-between}' +
'.hdr img{height:40px}' +
'.hdr-r{text-align:right;color:#c7c9c8;font-size:11px}' +
'.hdr-r strong{color:#FA4616;font-size:13px}' +
'.cover{background:#002657;min-height:260px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:40px 30px;page-break-after:always}' +
'.cover img{height:60px;margin-bottom:24px}' +
'.cover h1{color:#fff;font-size:26px;margin:0 0 8px;font-weight:700}' +
'.cover h2{color:#FA4616;font-size:16px;margin:0 0 16px;font-weight:400}' +
'.cover .meta{color:#c7c9c8;font-size:12px;line-height:1.8}' +
'.cover .tag{background:#FA4616;color:#fff;padding:4px 14px;border-radius:12px;font-size:11px;font-weight:700;display:inline-block;margin-top:12px}' +
'.wrap{padding:18px 0 36px}' +
'.card{background:#f8f9fb;border:1px solid #e5e7eb;border-radius:6px;padding:14px 16px;margin-bottom:14px}' +
'.card-blue{background:#eff6ff;border-left:3px solid #0021A5;padding:10px 14px;margin:10px 0;border-radius:0 4px 4px 0}' +
'.card-orange{background:#fff7f5;border-left:3px solid #FA4616;padding:10px 14px;margin:10px 0;border-radius:0 4px 4px 0}' +
'.card-green{background:#f0fdf4;border-left:3px solid #16a34a;padding:10px 14px;margin:10px 0;border-radius:0 4px 4px 0}' +
'table{width:100%;border-collapse:collapse;margin:10px 0;font-size:11.5px}' +
'th{background:#002657;color:#fff;padding:7px 9px;text-align:left;font-size:11px}' +
'td{border:1px solid #e5e7eb;padding:6px 9px;vertical-align:top}' +
'tr:nth-child(even) td{background:#f9fafb}' +
'h3{color:#0021A5;font-size:13px;margin:14px 0 7px}' +
'h4{color:#002657;font-size:12px;margin:10px 0 5px}' +
'.page-break{page-break-before:always}' +
'.gantt-cell{height:18px;background:#e5e7eb}' +
'.gantt-fill{height:18px}' +
'.dmaic-row{display:flex;margin:10px 0}' +
'.dmaic-phase{flex:1;text-align:center;padding:8px 4px;font-size:10px;font-weight:700;color:#fff}' +
'.lss-label{font-size:9.5px;font-weight:700;letter-spacing:.05em;text-transform:uppercase}' +
'.budget-total{background:#002657;color:#fff;font-weight:700;font-size:13px}' +
'.ftr{background:#002657;color:#c7c9c8;text-align:center;padding:8px;font-size:9px;margin:24px -10mm -14mm -10mm}' +
'</style>';

// ═══════════════════════════════════════════════════════
// BUILD HTML
// ═══════════════════════════════════════════════════════
var H = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>Project Plan — ' + esc(c.company) + '</title>' + css + '</head><body>';

// ── COVER PAGE ───────────────────────────────────────────
H += '<div class="cover">';
H += '<img src="https://legalgpts.com/wp-content/uploads/2026/02/lg_whiteorange_clear.png" alt="legalGPTs">';
H += '<h1>' + esc(c.projectTitle || 'Project Plan') + '</h1>';
H += '<h2>' + esc(c.company || '') + '</h2>';
H += '<div class="meta">';
H += 'Prepared For: <strong style="color:#fff">' + esc(c.name) + '</strong><br>';
if(c.email) H += esc(c.email) + '<br>';
if(c.phone) H += esc(c.phone) + '<br>';
H += 'Date: ' + today + '<br>';
H += 'Prepared By: legalGPTs | legalgpts.com';
H += '</div>';
H += '<div class="tag">' + esc(c.projectType || 'Development') + ' Engagement</div>';
H += '</div>';

// ── HEADER (appears after cover) ─────────────────────────
H += '<div class="hdr"><img src="https://legalgpts.com/wp-content/uploads/2026/02/lg_orangeblue_clear.png" alt="legalGPTs">';
H += '<div class="hdr-r"><strong>Project Plan</strong><br>' + esc(c.company) + ' | ' + today + '</div></div>';

// ── WRAP START ────────────────────────────────────────────
H += '<div class="wrap">';

// ── 1. PROJECT VISION & CHARTER ──────────────────────────
H += sectionHead('1. Project Vision & Charter', 'The why behind this engagement');
H += '<div class="card-orange"><strong>Problem Statement:</strong><br><em>' + esc(v.problemStatement) + '</em></div>';

H += '<div style="display:table;width:100%;margin-top:10px">';
H += '<div style="display:table-cell;width:50%;padding-right:8px;vertical-align:top">';
H += '<h4>Business Goals</h4>' + listItems(v.businessGoals);
H += '<h4>Success Metrics</h4>' + listItems(v.successMetrics);
H += '</div><div style="display:table-cell;width:50%;padding-left:8px;vertical-align:top">';
H += '<h4>In Scope</h4>' + listItems(arr(v.scope).length ? v.scope.inScope : []);
H += '<h4>Out of Scope</h4>' + listItems(arr(v.scope).length ? v.scope.outOfScope : []);
H += '</div></div>';

if(arr(v.assumptions).length){
  H += '<h4>Assumptions</h4>' + listItems(v.assumptions);
}
if(arr(v.constraints).length){
  H += '<h4>Constraints</h4>' + listItems(v.constraints);
}

// ── 2. LEAN SIX SIGMA — DMAIC ────────────────────────────
H += '<div class="page-break">';
H += sectionHead('2. Lean Six Sigma Framework', 'DMAIC methodology applied to this engagement');

// DMAIC visual bar
var dmaicColors = ['#002657','#0021A5','#FA4616','#16a34a','#7c3aed'];
var dmaicLabels = ['DEFINE','MEASURE','ANALYZE','IMPROVE','CONTROL'];
var dmaicDesc   = ['Problem & Scope','Current State Baseline','Root Cause Analysis','Solution Implementation','Sustain & Monitor'];
H += '<div class="dmaic-row">';
for(var di=0;di<5;di++){
  H += '<div class="dmaic-phase" style="background:' + dmaicColors[di] + ';margin-right:' + (di<4?'2px':'0') + '">';
  H += '<div class="lss-label">' + dmaicLabels[di] + '</div>';
  H += '<div style="font-size:9px;margin-top:3px;font-weight:400;color:rgba(255,255,255,0.85)">' + dmaicDesc[di] + '</div>';
  H += '</div>';
}
H += '</div>';

// DEFINE
var def = lss.define || {};
H += '<h3>Define Phase</h3>';
H += '<div class="card-blue"><strong>Problem Statement:</strong> ' + esc(def.problemStatement) + '</div>';
H += '<div class="card-blue"><strong>Project Charter:</strong> ' + esc(def.projectCharter) + '</div>';

// VOC
if(arr(def.voiceOfCustomer).length){
  H += '<h4>Voice of Customer (VOC)</h4>' + listItems(def.voiceOfCustomer);
}

// SIPOC Table
var sipoc = def.sipoc || {};
H += '<h4>SIPOC Diagram</h4>';
H += '<table><thead><tr>';
['Suppliers','Inputs','Process','Outputs','Customers'].forEach(function(h){ H += '<th style="background:' + ['#002657','#0021A5','#FA4616','#0021A5','#002657'][(['Suppliers','Inputs','Process','Outputs','Customers'].indexOf(h))] + '">' + h + '</th>'; });
H += '</tr></thead><tbody>';
var sipocMax = Math.max(
  arr(sipoc.suppliers).length, arr(sipoc.inputs).length,
  arr(sipoc.process).length, arr(sipoc.outputs).length, arr(sipoc.customers).length
);
for(var si=0;si<sipocMax;si++){
  H += '<tr>';
  [sipoc.suppliers, sipoc.inputs, sipoc.process, sipoc.outputs, sipoc.customers].forEach(function(col){
    H += '<td>' + esc((arr(col)[si])||'') + '</td>';
  });
  H += '</tr>';
}
H += '</tbody></table>';

// CTQ
if(arr(def.ctq).length){
  H += '<h4>Critical-to-Quality (CTQ) Requirements</h4>';
  H += '<table><thead><tr><th>Requirement</th><th>Specification</th><th>Measurement</th></tr></thead><tbody>';
  arr(def.ctq).forEach(function(q){
    H += '<tr><td><strong>' + esc(q.requirement) + '</strong></td><td>' + esc(q.specification) + '</td><td>' + esc(q.measurement) + '</td></tr>';
  });
  H += '</tbody></table>';
}

// MEASURE
var meas = lss.measure || {};
H += '<h3>Measure Phase</h3>';
H += '<div class="card">' + esc(meas.currentStateDescription) + '</div>';
if(arr(meas.baselineMetrics).length){
  H += '<table><thead><tr><th>Metric</th><th>Current State</th><th>Target</th><th>Unit</th></tr></thead><tbody>';
  arr(meas.baselineMetrics).forEach(function(m){
    H += '<tr><td>' + esc(m.metric) + '</td><td>' + esc(m.current) + '</td>';
    H += '<td style="color:#16a34a;font-weight:700">' + esc(m.target) + '</td><td>' + esc(m.unit) + '</td></tr>';
  });
  H += '</tbody></table>';
}

// ANALYZE
var anal = lss.analyze || {};
H += '<h3>Analyze Phase</h3>';
H += '<h4>Root Causes Identified</h4>' + listItems(anal.rootCauses);

// Fishbone summary table
var fb = anal.fishboneCategories || {};
var fbCats = ['people','process','technology','data','environment','measurement'];
H += '<h4>Fishbone (Ishikawa) Cause Categories</h4>';
H += '<table><thead><tr><th>Category</th><th>Contributing Factors</th></tr></thead><tbody>';
fbCats.forEach(function(cat){
  var items2 = arr(fb[cat]);
  if(items2.length){
    H += '<tr><td style="font-weight:700;color:#002657;text-transform:capitalize">' + cat + '</td>';
    H += '<td>' + items2.map(function(x){ return esc(x); }).join(' &bull; ') + '</td></tr>';
  }
});
H += '</tbody></table>';

// IMPROVE
var imp = lss.improve || {};
H += '<h3>Improve Phase</h3>';
if(arr(imp.solutions).length){
  H += '<table><thead><tr><th>Solution</th><th>Impact</th><th>Effort</th><th>Description</th></tr></thead><tbody>';
  arr(imp.solutions).forEach(function(s){
    H += '<tr><td><strong>' + esc(s.solution) + '</strong></td>';
    H += '<td>' + impactBadge(s.impact) + '</td>';
    H += '<td>' + impactBadge(s.effort) + '</td>';
    H += '<td>' + esc(s.description) + '</td></tr>';
  });
  H += '</tbody></table>';
}

// CONTROL
var ctrl = lss.control || {};
H += '<h3>Control Phase</h3>';
H += '<div class="card-green"><strong>Control Plan:</strong> ' + esc(ctrl.controlPlan) + '</div>';
if(arr(ctrl.kpis).length){
  H += '<h4>KPI Dashboard</h4>';
  H += '<table><thead><tr><th>KPI</th><th>Target</th><th>Frequency</th><th>Owner</th></tr></thead><tbody>';
  arr(ctrl.kpis).forEach(function(k){
    H += '<tr><td><strong>' + esc(k.kpi) + '</strong></td><td style="color:#0021A5;font-weight:700">' + esc(k.target) + '</td>';
    H += '<td>' + esc(k.frequency) + '</td><td>' + esc(k.owner) + '</td></tr>';
  });
  H += '</tbody></table>';
}
H += '</div>';

// ── 3. PRODUCT BACKLOG ────────────────────────────────────
H += '<div class="page-break">';
H += sectionHead('3. Product Backlog', 'Prioritized list of user stories and requirements');

var backlog = arr(p.backlog);
var epics = {};
backlog.forEach(function(us){ if(us.epic){ if(!epics[us.epic]) epics[us.epic]=[]; epics[us.epic].push(us); } });

H += '<table><thead><tr><th style="width:60px">ID</th><th>User Story</th><th style="width:80px">Epic</th><th style="width:70px">Priority</th><th style="width:40px">Pts</th><th style="width:50px">Sprint</th></tr></thead><tbody>';
backlog.forEach(function(us){
  H += '<tr><td style="font-weight:700;color:#0021A5">' + esc(us.id) + '</td>';
  H += '<td><div style="font-size:11px">' + esc(us.story) + '</div>';
  if(arr(us.acceptanceCriteria).length){
    H += '<div style="font-size:10px;color:#6b7280;margin-top:3px">AC: ' + arr(us.acceptanceCriteria).map(function(a){return esc(a);}).join('; ') + '</div>';
  }
  H += '</td>';
  H += '<td style="font-size:10px">' + esc(us.epic) + '</td>';
  H += '<td>' + badge(us.priority) + '</td>';
  H += '<td style="text-align:center;font-weight:700">' + (us.storyPoints||'') + '</td>';
  H += '<td style="text-align:center">S' + (us.sprintTarget||'') + '</td></tr>';
});
H += '</tbody></table>';

// Story Points Summary
var totalPts = backlog.reduce(function(acc,us){ return acc + (us.storyPoints||0); }, 0);
var critCount = backlog.filter(function(u){ return u.priority==='Critical'; }).length;
var highCount  = backlog.filter(function(u){ return u.priority==='High'; }).length;
H += '<div class="card" style="margin-top:10px">';
H += '<div style="display:table;width:100%"><div style="display:table-cell;text-align:center">';
H += '<strong style="font-size:20px;color:#002657">' + totalPts + '</strong><div style="font-size:10px;color:#6b7280">Total Story Points</div></div>';
H += '<div style="display:table-cell;text-align:center"><strong style="font-size:20px;color:#dc2626">' + critCount + '</strong><div style="font-size:10px;color:#6b7280">Critical Items</div></div>';
H += '<div style="display:table-cell;text-align:center"><strong style="font-size:20px;color:#FA4616">' + highCount + '</strong><div style="font-size:10px;color:#6b7280">High Priority</div></div>';
H += '<div style="display:table-cell;text-align:center"><strong style="font-size:20px;color:#0021A5">' + backlog.length + '</strong><div style="font-size:10px;color:#6b7280">Total User Stories</div></div>';
H += '</div></div>';
H += '</div>';

// ── 4. PRODUCT ROADMAP ────────────────────────────────────
H += '<div class="page-break">';
H += sectionHead('4. Product Roadmap', 'High-level milestones and delivery sequence');

var roadmap = arr(p.roadmap);
var totalWks = tl.totalWeeks || 12;

// Gantt chart — CSS table
H += '<table style="table-layout:fixed"><thead><tr>';
H += '<th style="width:28%">Phase / Milestone</th>';
for(var wk=1;wk<=totalWks;wk++){
  H += '<th style="text-align:center;padding:4px 2px;font-size:9px;width:' + (72/totalWks).toFixed(1) + '%">W' + wk + '</th>';
}
H += '</tr></thead><tbody>';
roadmap.forEach(function(row){
  H += '<tr>';
  H += '<td style="font-size:11px"><strong>' + esc(row.phase) + '</strong><br><span style="color:#6b7280;font-size:10px">' + esc(row.milestone) + '</span></td>';
  for(var wk2=1;wk2<=totalWks;wk2++){
    var inRange = wk2 >= (row.weeksStart||1) && wk2 <= (row.weeksEnd||1);
    if(inRange){
      H += '<td style="background:' + (row.colorHex||'#002657') + ';padding:0"></td>';
    } else {
      H += '<td style="background:#f3f4f6;padding:0"></td>';
    }
  }
  H += '</tr>';
  // Deliverables row
  if(arr(row.deliverables).length){
    H += '<tr><td colspan="' + (totalWks+1) + '" style="padding:2px 8px 8px 24px;font-size:9.5px;color:#6b7280;background:#fafafa">';
    H += '&#x21B3; ' + arr(row.deliverables).map(function(d){ return esc(d); }).join(' &bull; ');
    H += '</td></tr>';
  }
});
H += '</tbody></table>';

// Legend
H += '<div style="margin-top:8px;display:flex;gap:12px;align-items:center;font-size:10px;color:#6b7280">';
roadmap.forEach(function(row){
  H += '<span><span style="display:inline-block;width:12px;height:10px;background:' + (row.colorHex||'#002657') + ';border-radius:2px;margin-right:4px;vertical-align:middle"></span>' + esc(row.phase) + '</span>';
});
H += '</div>';

// ── 5. RELEASE PLANNING ───────────────────────────────────
H += '<h2 style="color:#002657;font-size:17px;border-bottom:2px solid #FA4616;padding-bottom:6px;margin:20px 0 12px">5. Release Planning</h2>';
var releases = arr(p.releases);
H += '<table><thead><tr><th style="width:60px">Release</th><th>Name & Description</th><th>Key Features</th><th style="width:80px">Sprints</th><th style="width:70px">Target Week</th></tr></thead><tbody>';
releases.forEach(function(r){
  H += '<tr>';
  H += '<td style="font-weight:700;color:#0021A5;font-size:13px">' + esc(r.version) + '</td>';
  H += '<td><strong>' + esc(r.name) + '</strong><br><span style="color:#6b7280;font-size:10px">' + esc(r.description) + '</span></td>';
  H += '<td><ul style="margin:0;padding-left:14px">' + arr(r.keyFeatures).map(function(f){ return '<li style="font-size:10.5px">' + esc(f) + '</li>'; }).join('') + '</ul></td>';
  H += '<td style="text-align:center">' + arr(r.sprints).map(function(s){ return 'S'+s; }).join(', ') + '</td>';
  H += '<td style="text-align:center;font-weight:700">Week ' + (r.targetWeek||'TBD') + '</td>';
  H += '</tr>';
});
H += '</tbody></table>';
H += '</div>';

// ── 6. SPRINT PLANNING ────────────────────────────────────
H += '<div class="page-break">';
H += '<div class="wrap">';
H += sectionHead('6. Sprint Planning & Backlog', 'Iteration plan — ' + (tl.totalSprints||0) + ' sprints, ' + (tl.totalWeeks||0) + ' weeks total');

var sprints = arr(p.sprints);
sprints.forEach(function(sp, si){
  H += '<div class="card" style="margin-bottom:14px;page-break-inside:avoid">';
  H += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">';
  H += '<div><strong style="color:#002657;font-size:13px">Sprint ' + sp.number + ': ' + esc(sp.name) + '</strong>';
  H += '<div style="font-size:10px;color:#6b7280">Weeks ' + sp.weeksStart + '–' + sp.weeksEnd + ' &bull; ' + esc(sp.duration) + '</div></div>';
  H += '<div style="text-align:right"><strong style="font-size:18px;color:#FA4616">' + (sp.storyPoints||0) + '</strong><div style="font-size:9px;color:#6b7280">story pts</div></div>';
  H += '</div>';
  H += '<div class="card-blue" style="margin-bottom:8px"><strong>Sprint Goal:</strong> ' + esc(sp.goal) + '</div>';

  // Tasks table
  if(arr(sp.tasks).length){
    H += '<table><thead><tr><th>Task</th><th style="width:80px">Type</th><th style="width:50px">Hours</th><th style="width:80px">Owner</th></tr></thead><tbody>';
    arr(sp.tasks).forEach(function(t){
      var typeColors = {Development:'#0021A5',PM:'#002657','Project Management':'#002657',Support:'#7c3aed',Training:'#16a34a'};
      var tc = typeColors[t.type] || '#6b7280';
      H += '<tr><td>' + esc(t.task) + '</td>';
      H += '<td><span style="color:' + tc + ';font-weight:700;font-size:10px">' + esc(t.type) + '</span></td>';
      H += '<td style="text-align:center">' + (t.hours||'') + '</td>';
      H += '<td style="font-size:10px">' + esc(t.owner) + '</td></tr>';
    });
    H += '</tbody></table>';
  }

  // Definition of Done
  if(arr(sp.definitionOfDone).length){
    H += '<div style="margin-top:8px;font-size:10.5px"><strong style="color:#002657">Definition of Done:</strong> ';
    H += arr(sp.definitionOfDone).map(function(d){ return '&#x2713; ' + esc(d); }).join(' &bull; ');
    H += '</div>';
  }
  H += '</div>';
